import{_ as r,o as a,c as o,a3 as t}from"./chunks/framework.CSV8cNZH.js";const u=JSON.parse('{"title":"Binance SDK error handling","description":"Interpret Binance API responses, HTTP failures and transport errors.","frontmatter":{"title":"Binance SDK error handling","description":"Interpret Binance API responses, HTTP failures and transport errors."},"headers":[],"relativePath":"guides/errors.md","filePath":"guides/errors.md"}'),n={name:"guides/errors.md"};function s(i,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h1><h2 id="http-and-transport-failures" tabindex="-1">HTTP and transport failures <a class="header-anchor" href="#http-and-transport-failures" aria-label="Permalink to &quot;HTTP and transport failures&quot;">​</a></h2><p>REST requests reject on HTTP and transport failures. With the default <code>parseExceptions</code> setting, a Binance HTTP error can expose <code>code</code>, <code>message</code>, <code>body</code> and <code>headers</code>. <code>code</code> is the Binance error code, not necessarily the HTTP status.</p><p>A connection failure can have a different shape, and thrown values are not always <code>Error</code> instances. Avoid assuming <code>error.response.data</code> exists for every failure.</p><h2 id="keep-original-transport-errors" tabindex="-1">Keep original transport errors <a class="header-anchor" href="#keep-original-transport-errors" aria-label="Permalink to &quot;Keep original transport errors&quot;">​</a></h2><p>Set <code>parseExceptions: false</code> in the first constructor argument when your application needs the original Axios error, including its HTTP response status. This setting uses camelCase in the Binance SDK.</p><h2 id="log-useful-fields" tabindex="-1">Log useful fields <a class="header-anchor" href="#log-useful-fields" aria-label="Permalink to &quot;Log useful fields&quot;">​</a></h2><p>Log the operation, symbol, HTTP status when available, and Binance error code. Do not serialize the whole error: request URLs and transport configuration can contain signatures or credentials even when selected fields have been redacted.</p><h2 id="decide-what-to-retry" tabindex="-1">Decide what to retry <a class="header-anchor" href="#decide-what-to-retry" aria-label="Permalink to &quot;Decide what to retry&quot;">​</a></h2><p>Correct validation, signature and permission failures before retrying. Limit retries for reads and apply backoff. A timeout after submitting an order does not prove rejection; query the order before deciding whether to resubmit.</p><p>See <a href="/docs/binance/guides/production.html">Production usage</a> and <a href="https://developers.binance.com/docs/binance-spot-api-docs/errors" target="_blank" rel="noreferrer">Binance&#39;s error reference</a>.</p>',11)])])}const f=r(n,[["render",s]]);export{u as __pageData,f as default};
